package com.spawnershop.data;
import org.bukkit.plugin.Plugin; import java.io.File; import java.sql.*; import java.util.UUID; import java.util.concurrent.*;
/** SQLite work is isolated on a single daemon worker; Bukkit state is never read there. */
public final class StatisticsRepository implements AutoCloseable { private final Plugin plugin; private final ExecutorService worker=Executors.newSingleThreadExecutor(r->{Thread t=new Thread(r,"SpawnerShop-Database");t.setDaemon(true);return t;}); private Connection connection;
 public StatisticsRepository(Plugin plugin){this.plugin=plugin;} public void start(){worker.execute(()->{try{connection=DriverManager.getConnection("jdbc:sqlite:"+new File(plugin.getDataFolder(),"database.db").getAbsolutePath());try(Statement s=connection.createStatement()){s.executeUpdate("CREATE TABLE IF NOT EXISTS transactions (uuid TEXT, item TEXT, amount INTEGER, value REAL, kind TEXT, time INTEGER)");}}catch(SQLException e){plugin.getLogger().severe("Database unavailable: "+e.getMessage());}});}
 public void log(UUID player,String item,int amount,double value,String kind){worker.execute(()->{if(connection==null)return;try(PreparedStatement s=connection.prepareStatement("INSERT INTO transactions VALUES (?,?,?,?,?,?)")){s.setString(1,player.toString());s.setString(2,item);s.setInt(3,amount);s.setDouble(4,value);s.setString(5,kind);s.setLong(6,System.currentTimeMillis());s.executeUpdate();}catch(SQLException e){plugin.getLogger().warning("Could not log transaction: "+e.getMessage());}});}
 @Override public void close(){worker.shutdown(); try{worker.awaitTermination(3,TimeUnit.SECONDS);}catch(InterruptedException e){Thread.currentThread().interrupt();} try{if(connection!=null)connection.close();}catch(SQLException ignored){}} }
